function ag_sd_artwork_library() {
    $names=array('classic'=>'Classic / Elegant','ocean'=>'Ocean / Coastal','forest'=>'Forest / Nature','christmas'=>'Christmas','halloween'=>'Halloween','easter'=>'Easter','spring'=>'Spring','summer'=>'Summer / Beach','autumn'=>'Autumn','community'=>'Community','marketplace'=>'Marketplace','fantasy'=>'Fantasy / Roleplay','festival'=>'Events / Festival','abstract'=>'Modern Dark','minimal'=>'Modern Light');
    $out=array();foreach($names as $id=>$name){$path=dirname(__DIR__,2).'/site-design/artwork/'.$id.'.png';$out[$id]=array('name'=>$name,'url'=>'/Other/site-design/artwork/'.$id.'.png'.(is_file($path)?'?v='.filemtime($path):''),'path'=>$path);}return $out;
}
