function ag_sd_extend_presets($presets) {
    foreach(ag_sd_theme_content() as $id=>$content){
        $theme=$presets[$id] ?? array('name'=>$content['name'],'font'=>$content['font'],'colors'=>array_combine(array('background','surface','text','muted','accent','border'),$content['colors']));
        $theme['font']=$content['font'];$theme['styles']=array_merge(ag_sd_style_defaults(),array('treatment'=>$content['treatment'],'artwork'=>$content['art'],'radius'=>$content['radius'],'button'=>$content['button']));$presets[$id]=$theme;
    }return $presets;
}
function ag_sd_design_css($styles,$scope='public') {
    $s=ag_sd_styles($styles);$dark=in_array($s['treatment'],array('classic','coastal','botanical','festive','haunted','harvest','fantasy','festival','modern'),true);
    $t=$s['treatment'];$shadow=in_array($t,array('coastal','fantasy','festival'),true)?'0 18px 60px rgba(0,0,0,.28)':'0 12px 30px rgba(0,0,0,.10)';
    $css='--site-card-shadow:'.$shadow.';--site-hero-spacing:'.($scope==='admin'?'28':'64').'px;--site-hero-letter-spacing:'.(in_array($t,array('classic','haunted','fantasy'),true)?'.02em':'-.035em').';';
    $css.='--site-panel-treatment:'.($s['panel']==='outlined'?'var(--site-background)':($scope==='admin'?'var(--site-surface)':($dark?'linear-gradient(145deg,color-mix(in srgb,var(--site-surface) 94%,white),color-mix(in srgb,var(--site-surface) 96%,transparent))':'var(--site-surface)'))).';';
    $css.='--site-hero-rule:'.(in_array($t,array('classic','editorial','harvest'),true)?'3px solid var(--site-accent)':'0 solid transparent').';';
    $art=$s['artwork'];if($art!==''&&$s['background']===''){$a=ag_sd_artwork_library()[$art];if(is_file($a['path']))$css.='--site-background-image:linear-gradient('.($scope==='admin'?'rgba(0,0,0,.65),rgba(0,0,0,.65)':($dark?'rgba(0,0,0,.12),rgba(0,0,0,.18)':'rgba(255,255,255,.12),rgba(255,255,255,.12)')).'),url("'.$a['url'].'");';}
    return $css;
}
function ag_sd_visual_card($theme,$title,$scope='public',$layout='') {
    $t=ag_sa_theme(empty($theme['colors'])?ag_sa_presets()['classic-gold']:$theme);if(empty($theme['colors']))$t['styles']=ag_sd_style_defaults();$s=$t['styles'];$art=ag_sd_artwork_library()[$s['artwork']] ?? null;$bg=$s['background']?ag_sd_asset_url($s['background']):($art['url'] ?? '');$font=ag_pd_font_catalog()[$t['font']]['css'];
    $style=implode(';',array_map(function($key,$value){return '--site-'.$key.':'.$value;},array_keys($t['colors']),array_values($t['colors']))).';'.ag_sd_style_css($s).ag_sd_design_css($s,$scope).';font-family:'.$font;
    return '<div class="design-mini" data-treatment="'.ag_pd_h($s['treatment']).'" data-layout="'.ag_pd_h(isset(ag_sd_starters()[$layout])?$layout:'').'" style="'.ag_pd_h($style).'">'.($bg?'<img class="mini-art" loading="lazy" src="'.ag_pd_h($bg).'" alt="">':'').'<div class="mini-heading"><small>EXPLORE · CONNECT · CREATE</small><strong>'.ag_pd_h($title).'</strong><span>A world of possibilities</span></div><div class="mini-panel"><span>Member Login</span><i></i><i></i><b>Welcome in</b></div><div class="mini-tiles"><span></span><span></span><span></span></div></div>';
}
function ag_sd_apply_artwork($art,$upload,$target,$revision) {
    if($art!==''&&!isset(ag_sd_artwork_library()[$art]))throw new RuntimeException('Choose built-in artwork.');$upload=ag_sd_asset_name($upload);if($upload!==''&&!ag_sd_asset_path($upload))throw new RuntimeException('Uploaded artwork is missing.');
    if(!in_array($target,array('public','admin','user','designer','current-theme'),true))throw new RuntimeException('Choose an artwork destination.');
    return ag_sa_change($revision,function($s)use($art,$upload,$target){$scopes=$target==='current-theme'?array_keys(array_filter($s['scopes'],function($id)use($s){return $id===$s['scopes']['public'];})):array($target);foreach($scopes as $scope){if(count($s['themes'])>=50)throw new RuntimeException('Remove an unused saved theme first.');$theme=ag_sd_active_theme($s,$scope);if(empty($theme['colors']))$theme=ag_sa_presets()['classic-gold'];$theme=ag_sa_theme($theme);$defaultArt=$art;if($art===''&&$upload==='')foreach(ag_sd_theme_content() as $content)if($content['treatment']===$theme['styles']['treatment']){$defaultArt=$content['art'];break;}$theme['styles']['artwork']=$defaultArt;$theme['styles']['background']=$upload;$theme['name']=ag_pd_text($theme['name'].' artwork',80);$id=bin2hex(random_bytes(8));$s['themes'][$id]=$theme;$s['scopes'][$scope]=$id;$s['activeThemes'][$scope]=$theme;}return $s;},array('label'=>$art===''&&$upload===''?'Restore theme artwork default':'Apply artwork','scopes'=>$target==='current-theme'?array_keys(ag_sd_scopes()):array($target)));
}
